package com.vriksha.academy.service;
import com.vriksha.academy.model.User; import com.vriksha.academy.repository.UserRepository; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class UserService { private final UserRepository repo; private final BCryptPasswordEncoder enc=new BCryptPasswordEncoder(); public UserService(UserRepository r){repo=r;} public User register(String name,String email,String pass){String e=email.trim().toLowerCase(); if(repo.existsByEmailIgnoreCase(e)) throw new IllegalArgumentException("An account with this email already exists."); User u=new User();u.setName(name.trim());u.setEmail(e);u.setPassword(enc.encode(pass));return repo.save(u);} public Optional<User> login(String email,String pass){return repo.findByEmailIgnoreCase(email.trim().toLowerCase()).filter(u->enc.matches(pass,u.getPassword()));} }
